protected override Task<AuthenticateResult> HandleAuthenticateAsync()
        {
            if (!environment.IsDevelopment())
            {
                return Task.FromResult(AuthenticateResult.Fail("Development sign-in is disabled outside Development."));
            }

            var user = Request.Headers[DevHeader].ToString();
            if (string.IsNullOrWhiteSpace(user))
            {
                return Task.FromResult(AuthenticateResult.NoResult());
            }

            var identity = new ClaimsIdentity([new Claim(ClaimTypes.NameIdentifier, user.Trim())], DevScheme);
            return Task.FromResult(AuthenticateResult.Success(new AuthenticationTicket(new ClaimsPrincipal(identity), DevScheme)));
        }

public async Task<AppReporter?> AuthenticateAsync(string? presentedKey, CancellationToken ct)
    {
        var prefix = ApiKey.PrefixOf(presentedKey);
        if (prefix is null)
        {
            return null;
        }

        var project = await projects.FindByKeyPrefixAsync(prefix, ct).ConfigureAwait(false);
        var match = project?.Authenticate(presentedKey!, clock.Now);
        return match is null ? null : new AppReporter(project!, match.Value.Environment);
    }

public async Task<IReadOnlyList<ActivityEvent>> RangeAsync(ProjectId id, DateTimeOffset from, DateTimeOffset to, UserId user, CancellationToken ct)
